ise: 15pt;\n	}\n	\n	.actions .button_block .pad i {\n		letter-spacing: 25px;\n		mso-font-width: -100%;\n	}\n\n	.footer {\n		clear: both;\n		padding: 24px 0;\n		width: 100%;\n	}\n\n	.footer td,\n	.footer p,\n	.footer span,\n	.footer a {\n		color: #101517;\n		font-size: 12px;\n	}\n\n	h1 {\n		font-size: 20px;\n	}\n\n	p {\n		font-family: sans-serif;\n		font-size: 16px;\n		font-weight: normal;\n		margin: 0;\n		margin-bottom: 16px;\n	}\n\n	.powered-by a {\n		text-decoration: none;\n	}\n\n	@media only screen and (max-width: 640px) {\n		.main p,\n		.main td,\n		.main span {\n			font-size: 16px !important;\n		}\n\n		.wrapper {\n			padding: 8px 16px !important;\n		}\n\n		.powered-by {\n			padding: 0 16px 16px!important;\n		}\n\n		.content {\n			padding: 0 !important;\n		}\n\n		.container {\n			padding: 0 !important;\n			padding-top: 8px !important;\n			width: 100% !important;\n		}\n\n		.main {\n			border-left-width: 0 !important;\n			border-radius: 0 !important;\n			border-right-width: 0 !important;\n		}\n\n		.collapse { display: none; }\n\n		h1 { padding:0 16px; }\n	}\n\n	@media all {\n		.ExternalClass {\n			width: 100%;\n		}\n\n		.ExternalClass,\n		.ExternalClass p,\n		.ExternalClass span,\n		.ExternalClass font,\n		.ExternalClass td,\n		.ExternalClass div {\n			line-height: 100%;\n		}\n\n		.apple-link a {\n			color: inherit !important;\n			font-family: inherit !important;\n			font-size: inherit !important;\n			font-weight: inherit !important;\n			line-height: inherit !important;\n			text-decoration: none !important;\n		}\n\n		#MessageViewBody a {\n			color: inherit;\n			text-decoration: none;\n			font-size: inherit;\n			font-family: inherit;\n			font-weight: inherit;\n			line-height: inherit;\n		}\n	}\n</style>\n</head>\n<body>\n<table role=\"presentation\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" class=\"body\">\n<tr>\n<td class=\"collapse\">&nbsp;</td>\n<td class=\"container\">\n<div class=\"content\">\n<span class=\"preheader\"></span>\n<table role=\"presentatio