════════════════\n   RESET & ROOT\n═══════════════════════════════ */\n*, *::before, *::after { margin:0; padding:0; box-sizing:border-box; }\n\n:root {\n  --navy:        #071e3d;\n  --navy-mid:    #0f3875;\n  --blue:        #1a6cf6;\n  --blue-mid:    #2563eb;\n  --blue-light:  #3b82f6;\n  --blue-pale:   #60a5fa;\n  --sky:         #e0eeff;\n  --sky-pale:    #f0f7ff;\n  --gold:        #f59e0b;\n  --gold-dark:   #d97706;\n  --gold-light:  #fef3c7;\n  --green:       #10b981;\n  --green-light: #d1fae5;\n  --purple:      #7c3aed;\n  --purple-light:#ede9fe;\n  --red:         #ef4444;\n  --red-light:   #fee2e2;\n  --white:       #ffffff;\n  --slate:       #64748b;\n  --slate-dark:  #334155;\n  --gray-50:     #f8fafc;\n  --gray-100:    #f1f5f9;\n  --gray-200:    #e2e8f0;\n  --r-sm:  10px;\n  --r-md:  14px;\n  --r-lg:  18px;\n  --r-xl:  26px;\n  --r-2xl: 34px;\n  --sh-sm:   0 2px 10px rgba(7,30,61,.08);\n  --sh-md:   0 8px 32px rgba(7,30,61,.13);\n  --sh-lg:   0 20px 60px rgba(7,30,61,.18);\n  --sh-blue: 0 10px 40px rgba(26,108,246,.28);\n  --sh-gold: 0 10px 36px rgba(245,158,11,.3);\n}\n\nhtml { scroll-behavior: smooth; }\n\nbody {\n  font-family: \'Plus Jakarta Sans\', sans-serif;\n  background: #d6e8ff;\n  padding: 0;\n  margin: 0;\n  color: var(--slate-dark);\n  line-height: 1.78;\n  -webkit-font-smoothing: antialiased;\n}\n\n/* WordPress full-width wrapper */\n.ssk-page {\n  max-width: 100%;\n  width: 100%;\n  background: var(--white);\n  overflow-x: hidden;\n}\n\n/* inner content constraint */\n.ssk-inner {\n  max-width: 1180px;\n  margin: 0 auto;\n  padding: 0 32px;\n}\n\na { color: var(--blue); text-decoration: none; }\na:hover { text-decoration: underline; }\n\n/* ═══════════════════════════════\n   SCROLL TICKER (top)\n═══════════════════════════════ */\n.ssk-ticker {\n  background: var(--navy);\n  overflow: hidden;\n  height: 38px;\n  display: flex;\n  align-items: center;\n}\n.ssk-ticker-track {\n  display: flex;\n  gap: 0;\n  animation: tickerScroll 30s linear infinite;\n  white-space: nowrap;\n  flex-shrink: 0;\n}\n.ssk-ticker-track span {\n  color: rgba(255,255,255,.75);\n  font-size: .78em;\n  font-weight: 600;\n  letter-spacing: .6px;\n  padding: 0 28px;\n  border-right: 1px solid rgba(255,255,255,.15);\n}\n.ssk-ticker-track span strong { color: #fcd34d; }\n@keyframes tickerScroll {\n  from { transform: translateX(0); }\n  to   { transform: translateX(-50%); }\n}\n\n/* ═══════════════════════════════\n   HERO\n═══════════════════════════════ */\n.ssk-hero {\n  position: relative;\n  overflow: hidden;\n  padding: 100px 32px 90px;\n  background: linear-gradient(150deg, var(--navy) 0%, #0f3875 50%, #1a56cc 100%);\n  text-align: center;\n}\n.ssk-hero-mesh {\n  position:absolute; inset:0; pointer-events:none;\n  background:\n    radial-gradient(ellipse 65% 75% at 8% 65%, rgba(26,108,246,.42) 0%, transparent 65%),\n    radial-gradient(ellipse 55% 65% at 92% 20%, rgba(245,158,11,.22) 0%, transparent 60%),\n    radial-gradient(ellipse 45% 55% at 50% 105%, rgba(59,130,246,.28) 0%, transparent 60%);\n}\n.ssk-hero-grid {\n  position:absolute; inset:0; pointer-events:none;\n  background-image:\n    linear-gradient(rgba(255,255,255,.04) 1px, transparent 1px),\n    linear-gradient(90deg, rgba(255,255,255,.04) 1px, transparent 1px);\n  background-size: 44px 44px;\n}\n/* Floating orbs */\n.ssk-orb {\n  position:absolute; border-radius:50%; pointer-events:none;\n  animation: orbFloat 6s ease-in-out infinite;\n}\n.ssk-orb-1 { width:180px;height:180px; background:radial-gradient(circle,rgba(26,108,246,.25),transparent 70%); top:-40px;right:8%; animation-delay:-1s; }\n.ssk-orb-2 { width:120px;height:120px; background:radial-gradient(circle,rgba(245,158,11,.2),transparent 70%); bottom:30px;left:5%; animation-delay:-3s; }\n.ssk-orb-3 { width:90px;height:90px;  background:radial-gradient(circle,rgba(96,165,250,.3),transparent 70%); top:40%;right:2%; animation-delay:-2s; }\n@keyframes orbFloat {\n  0%,100% { transform:translateY(0) scale(1); }\n  50%      { transform:translateY(-22px) scale(1.08); }\n}\n\n.ssk-hero-badge {\n  display:inline-flex; align-items:center; gap:9px;\n  background:rgba(245,158,11,.18);\n  border:1.5px solid rgba(245,158,11,.4);\n  color:#fcd34d;\n  font-size:.8em; font-weight:800;\n  letter-spacing:.9px; text-transform:uppercase;\n  padding:8px 24px; border-radius:50px;\n  margin-bottom:28px;\n  position:relative; z-index:3;\n  animation: heroUp .85s .05s cubic-bezier(.22,1,.36,1) both;\n}\n.ssk-hero-badge::before { content:\'\'; width:8px; height:8px; background:#fcd34d; border-radius:50%; animation:blink 1.5s infinite; }\n@keyframes blink { 0%,100%{opacity:1;transform:scale(1)} 50%{opacity:.4;transform:scale(.7)} }\n\n.ssk-hero h1 {\n  font-family:\'Fraunces\',serif;\n  font-size: clamp(2.4em, 6vw, 4.4em);\n  color: var(--white);\n  line-height: 1.08;\n  position:relative; z-index:3;\n  animation: heroUp .85s .15s cubic-bezier(.22,1,.36,1) both;\n  letter-spacing: -.02em;\n}\n.ssk-hero h1 .hl-blue  { color:#60a5fa; }\n.ssk-hero h1 .hl-gold  { color:#fcd34d; }\n\n.ssk-hero-sub {\n  color:rgba(255,255,255,.78); font-size:1.18em;\n  max-width:680px; margin:22px auto 0;\n  position:relative; z-index:3;\n  animation: heroUp .85s .27s cubic-bezier(.22,1,.36,1) both;\n}\n\n/* STATS ROW */\n.ssk-hero-stats {\n  display:flex; flex-wrap:wrap; justify-content:center; gap:22px;\n  margin:44px 0 36px;\n  position:relative; z-index:3;\n  animation: heroUp .85s .38s cubic-bezier(.22,1,.36,1) both;\n}\n.ssk-stat {\n  background:rgba(255,255,255,.1);\n  border:1.5px solid rgba(255,255,255,.2);\n  border-radius:16px;\n  padding:18px 26px;\n  min-width:130px;\n  backdrop-filter:blur(10px);\n  transition:all .35s ease;\n  cursor:default;\n}\n.ssk-stat:hover {\n  background:rgba(255,255,255,.2);\n  border-color:rgba(255,255,255,.45);\n  transform:translateY(-8px);\n  box-shadow:0 16px 36px rgba(0,0,0,.2);\n}\n.ssk-stat-num {\n  display:block;\n  font-family:\'Fraunces\',serif;\n  font-size:2em; font-weight:900;\n  color:var(--white); line-height:1;\n  margin-bottom:4px;\n}\n.ssk-stat-num .gold { color:#fcd34d; }\n.ssk-stat-label {\n  font-size:.8em; color:rgba(255,255,255,.65);\n  font-weight:600; text-transform:uppercase; letter-spacing:.5px;\n}\n\n/* HERO TAGS */\n.ssk-hero-tags {\n  display:flex; flex-wrap:wrap; justify-content:center; gap:10px;\n  position:relative; z-index:3;\n  animation: heroUp .85s .48s cubic-bezier(.22,1,.36,1) both;\n}\n.ssk-hero-tag {\n  background:rgba(255,255,255,.1);\n  border:1px solid rgba(255,255,255,.2);\n  color:rgba(255,255,255,.88);\n  padding:9px 20px; border-radius:50px;\n  font-size:.87em; font-weight:500;\n  transition:all .3s ease; cursor:default;\n}\n.ssk-hero-tag:hover {\n  background:rgba(255,255,255,.22);\n  border-color:rgba(255,255,255,.5);\n  transform:translateY(-4px);\n}\n\n/* SCROLL CUE */\n.ssk-scroll-cue {\n  position:relative; z-index:3;\n  margin-top:44px;\n  animation: heroUp .85s .6s cubic-bezier(.22,1,.36,1) both;\n}\n.ssk-scroll-cue span {\n  font-size:.75em; color:rgba(255,255,255,.5);\n  text-transform:uppercase; letter-spacing:1.5px;\n  display:block; margin-bottom:8px;\n}\n.ssk-scroll-arrow {\n  width:36px;height:36px;\n  border:2px solid rgba(255,255,255,.25);\n  border-radius:50%; margin:0 auto;\n  display:flex; align-items:center; justify-content:center;\n  animation:bounce 2s infinite;\n  cursor:pointer;\n  transition:all .3s ease;\n}\n.ssk-scroll-arrow:hover { border-color:rgba(255,255,255,.6); background:rgba(255,255,255,.1); }\n.ssk-scroll-arrow svg { width:14px;height:14px; fill:none; stroke:rgba(255,255,255,.6); stroke-width:2; }\n@keyframes bounce { 0%,100%{transform:translateY(0)} 50%{transform:translateY(8px)} }\n\n@keyframes heroUp { from{opacity:0;transform:translateY(26px)} to{opacity:1;transform:none} }\n\n/* ═══════════════════════════════\n   SCROLL MARQUEE (below hero)\n═══════════════════════════════ */\n.ssk-marquee-wrap {\n  background:var(--blue);\n  overflow:hidden; height:44px;\n  display:flex; align-items:center;\n}\n.ssk-marquee-track {\n  display:flex; animation:marquee 22s linear infinite;\n  white-space:nowrap;\n}\n.ssk-marquee-track span {\n  color:rgba(255,255,255,.85);\n  font-size:.8em; font-weight:700;\n  letter-spacing:.6px; text-transform:uppercase;\n  padding:0 24px;\n}\n.ssk-marquee-track span::after { content:\'★\'; color:rgba(255,255,255,.4); margin-left:24px; }\n@keyframes marquee { from{transform:translateX(0)} to{transform:translateX(-50%)} }\n\n/* ═══════════════════════════════\n   INTRO BAND\n═══════════════════════════════ */\n.ssk-intro-section { padding:64px 32px 0; }\n.ssk-intro-band {\n  background:linear-gradient(135deg, var(--sky-pale), #daeeff);\n  border-left:5px solid var(--blue);\n  border-radius:var(--r-lg);\n  padding:34px 40px;\n  font-size:1.08em;\n  box-shadow:var(--sh-sm);\n}\n.ssk-intro-band p + p { margin-top:14px; }\n.ssk-intro-band strong { color:var(--navy); }\n\n/* ═══════════════════════════════\n   SECTION HEADINGS\n═══════════════════════════════ */\n.ssk-section { padding:56px 32px 0; }\n.ssk-h2 {\n  font-family:\'Fraunces\',serif;\n  font-size: clamp(1.7em,3vw,2.2em);\n  color:var(--navy);\n  margin-bottom:28px;\n  padding-bottom:16px;\n  border-bottom:2px solid var(--gray-200);\n  position:relative;\n  display:flex; align-items:center; gap:13px;\n}\n.ssk-h2::after {\n  content:\'\';\n  position:absolute; bottom:-2px; left:0;\n  height:2px; width:56px;\n  background:var(--blue);\n  transition:width .55s ease;\n}\n.ssk-h2:hover::after { width:100%; }\n\n.ssk-h3 {\n  font-family:\'Fraunces\',serif;\n  font-size:1.35em; color:var(--navy);\n  margin-bottom:14px;\n}\n\n.ssk-lead {\n  font-size:1.07em; color:var(--slate);\n  margin-bottom:28px; line-height:1.8;\n}\n\n/* ═══════════════════════════════\n   QUOTE BOX\n═══════════════════════════════ */\n.ssk-quote {\n  position:relative;\n  background:var(--gold-light);\n  border-left:5px solid var(--gold);\n  border-radius:var(--r-lg);\n  padding:24px 30px 24px 62px;\n  margin:34px 0;\n  font-style:italic; font-size:1.12em;\n  color:#92400e;\n  box-shadow:0 4px 20px rgba(245,158,11,.15);\n  transition:transform .38s ease, box-shadow .38s ease;\n  cursor:default;\n}\n.ssk-quote::before {\n  content:\'\\201C\';\n  position:absolute; left:16px; top:6px;\n  font-family:\'Fraunces\',serif;\n  font-size:3.8em; color:var(--gold);\n  opacity:.4; line-height:1;\n}\n.ssk-quote:hover { transform:scale(1.022); box-shadow:0 10px 32px rgba(245,158,11,.3); }\n\n/* ═══════════════════════════════\n   DIVIDER\n═══════════════════════════════ */\n.ssk-divider {\n  height:1px;\n  background:linear-gradient(90deg,transparent,var(--gray-200),transparent);\n  margin:56px 0 0;\n}\n\n/* ═══════════════════════════════\n   WHY CARDS\n═══════════════════════════════ */\n.ssk-why-grid {\n  display:grid;\n  grid-template-columns:repeat(auto-fill,minmax(240px,1fr));\n  gap:18px;\n}\n.ssk-why-card {\n  background:var(--white);\n  border:2px solid var(--gray-200);\n  border-radius:var(--r-lg);\n  padding:28px 24px;\n  display:flex; flex-direction:column; gap:12px;\n  box-shadow:var(--sh-sm);\n  transition:all .4s cubic-bezier(.34,1.56,.64,1);\n  cursor:default; position:relative; overflow:hidden;\n}\n.ssk-why-card::after {\n  content:\'\';\n  position:absolute; bottom:0; left:0; right:0; height:3px;\n  background:linear-gradient(90deg,var(--blue),var(--blue-light));\n  transform:scaleX(0); transform-origin:left;\n  transition:transform .4s ease;\n}\n.ssk-why-card:hover::after { transform:scaleX(1); }\n.ssk-why-card:hover {\n  border-color:var(--sky);\n  transform:translateY(-10px) scale(1.025);\n  box-shadow:var(--sh-blue);\n}\n.ssk-why-card:active { transform:scale(.97); }\n.ssk-why-icon {\n  width:50px; height:50px;\n  background:linear-gradient(135deg,var(--sky),#bfdbfe);\n  border-radius:14px;\n  display:flex; align-items:center; justify-content:center;\n  font-size:1.45em;\n  transition:transform .4s cubic-bezier(.34,1.56,.64,1), background .3s;\n}\n.ssk-why-card:hover .ssk-why-icon {\n  background:linear-gradient(135deg,var(--blue),#1d4ed8);\n  transform:scale(1.2) rotate(-8deg);\n}\n.ssk-why-card strong { font-size:1.07em; color:var(--navy); }\n.ssk-why-card p { font-size:.93em; color:var(--slate); }\n\n/* ═══════════════════════════════\n   WHAT IS SECTION — split layout\n═══════════════════════════════ */\n.ssk-split {\n  display:grid;\n  grid-template-columns:1fr 1fr;\n  gap:40px; align-items:start;\n  margin-top:8px;\n}\n@media(max-width:740px){ .ssk-split{grid-template-columns:1fr;} }\n\n.ssk-split-text p { margin-bottom:16px; font-size:1.03em; color:var(--slate-dark); }\n.ssk-split-text p strong { color:var(--navy); }\n\n.ssk-info-panel {\n  background:linear-gradient(145deg,var(--navy),#1a3a6c);\n  border-radius:var(--r-xl);\n  padding:34px 30px;\n  color:var(--white);\n  box-shadow:var(--sh-blue);\n  position:relative; overflow:hidden;\n}\n.ssk-info-panel::before {\n  content:\'\';\n  position:absolute; top:-40px; right:-40px;\n  width:160px; height:160px;\n  background:radial-gradient(circle,rgba(26,108,246,.4),transparent 70%);\n  border-radius:50%;\n}\n.ssk-info-panel h3 {\n  font-family:\'Fraunces\',serif;\n  font-size:1.25em; margin-bottom:20px;\n  color:var(--white);\n}\n.ssk-info-row {\n  display:flex; align-items:flex-start; gap:12px;\n  padding:12px 0;\n  border-bottom:1px solid rgba(255,255,255,.1);\n}\n.ssk-info-row:last-child { border-bottom:none; }\n.ssk-info-icon {\n  width:34px;height:34px; flex-shrink:0;\n  background:rgba(255,255,255,.12);\n  border-radius:9px;\n  display:flex;align-items:center;justify-content:center;\n  font-size:1em;\n  transition:background .3s, transform .3s;\n}\n.ssk-info-row:hover .ssk-info-icon { background:var(--blue); transform:scale(1.12); }\n.ssk-info-row div strong { display:block; font-size:.88em; color:rgba(255,255,255,.6); text-transform:uppercase; letter-spacing:.5px; margin-bottom:2px; }\n.ssk-info-row div span { font-size:.97em; color:var(--white); font-weight:500; }\n\n/* ═══════════════════════════════\n   5 PILLARS\n═══════════════════════════════ */\n.ssk-pillars {\n  display:grid;\n  grid-template-columns:repeat(auto-fill,minmax(200px,1fr));\n  gap:16px;\n}\n.ssk-pillar {\n  background:var(--white);\n  border:2px solid var(--gray-200);\n  border-radius:16px;\n  padding:26px 20px;\n  text-align:center;\n  box-shadow:var(--sh-sm);\n  transition:all .42s cubic-bezier(.34,1.56,.64,1);\n  cursor:default; position:relative; overflow:hidden;\n}\n.ssk-pillar:hover {\n  background:linear-gradient(145deg,var(--blue),#1d4ed8);\n  border-color:var(--blue);\n  transform:translateY(-12px) scale(1.04);\n  box-shadow:var(--sh-blue);\n  color:var(--white);\n}\n.ssk-pillar-num {\n  font-family:\'Fraunces\',serif;\n  font-size:2.4em; font-weight:900;\n  color:var(--gray-200);\n  transition:color .3s;\n  line-height:1;\n}\n.ssk-pillar:hover .ssk-pillar-num { color:rgba(255,255,255,.2); }\n.ssk-pillar-icon { font-size:1.8em; margin:8px 0; }\n.ssk-pillar strong { display:block; font-size:.96em; color:var(--navy); transition:color .3s; }\n.ssk-pillar:hover strong { color:var(--white); }\n.ssk-pillar p { font-size:.86em; color:var(--slate); margin-top:6px; transition:color .3s; }\n.ssk-pillar:hover p { color:rgba(255,255,255,.8); }\n\n/* ═══════════════════════════════\n   KEYWORDS\n═══════════════════════════════ */\n.ssk-kw-grid {\n  display:grid;\n  grid-template-columns:repeat(auto-fill,minmax(210px,1fr));\n  gap:14px;\n}\n.ssk-kw-item {\n  background:var(--white);\n  border:2px solid var(--gray-200);\n  border-radius:13px;\n  padding:16px 18px;\n  display:flex; align-items:center; gap:13px;\n  box-shadow:var(--sh-sm);\n  font-weight:500; font-size:.95em;\n  transition:all .38s cubic-bezier(.34,1.56,.64,1);\n  cursor:default;\n}\n.ssk-kw-item:hover {\n  background:var(--blue);\n  color:var(--white);\n  border-color:var(--blue);\n  transform:translateY(-7px) scale(1.04);\n  box-shadow:var(--sh-blue);\n}\n.ssk-kw-num {\n  width:32px;height:32px;flex-shrink:0;\n  background:var(--sky); color:var(--blue);\n  border-radius:50%; display:flex; align-items:center; justify-content:center;\n  font-weight:700; font-size:.85em;\n  transition:background .3s, color .3s;\n}\n.ssk-kw-item:hover .ssk-kw-num { background:rgba(255,255,255,.22); color:var(--white); }\n\n/* ═══════════════════════════════\n   AI SEO 2026 SECTION\n═══════════════════════════════ */\n.ssk-ai-grid {\n  display:grid;\n  grid-template-columns:repeat(auto-fill,minmax(260px,1fr));\n  gap:18px;\n}\n.ssk-ai-card {\n  background:var(--white);\n  border:2px solid var(--gray-200);\n  border-radius:var(--r-lg);\n  padding:28px 24px;\n  box-shadow:var(--sh-sm);\n  transition:all .4s cubic-bezier(.34,1.56,.64,1);\n  cursor:default; overflow:hidden; position:relative;\n}\n.ssk-ai-card::before {\n  content:\'\';\n  position:absolute; top:0; left:0; right:0; height:4px;\n  background:linear-gradient(90deg,var(--blue-mid),var(--blue-light));\n  transform:scaleX(0); transform-origin:left;\n  transition:transform .4s ease;\n}\n.ssk-ai-card:hover::before { transform:scaleX(1); }\n.ssk-ai-card:hover {\n  border-color:var(--sky);\n  transform:translateY(-10px);\n  box-shadow:var(--sh-blue);\n}\n.ssk-ai-tag {\n  display:inline-block;\n  background:var(--sky); color:var(--blue);\n  font-size:.75em; font-weight:700;\n  padding:4px 12px; border-radius:50px;\n  text-transform:uppercase; letter-spacing:.5px;\n  margin-bottom:12px;\n  transition:background .3s, color .3s;\n}\n.ssk-ai-card:hover .ssk-ai-tag { background:var(--blue); color:var(--white); }\n.ssk-ai-card h3 { font-family:\'Fraunces\',serif; font-size:1.12em; color:var(--navy); margin-bottom:10px; }\n.ssk-ai-card p { font-size:.93em; color:var(--slate); }\n\n/* ═══════════════════════════════\n   TOOLS\n═══════════════════════════════ */\n.ssk-tools-grid {\n  display:grid;\n  grid-template-columns:repeat(auto-fill,minmax(270px,1fr));\n  gap:15px;\n}\n.ssk-tool-card {\n  background:var(--gray-50);\n  border:2px solid var(--gray-200);\n  border-radius:15px;\n  padding:20px 22px;\n  display:flex; align-items:flex-start; gap:15px;\n  box-shadow:var(--sh-sm);\n  transition:all .4s cubic-bezier(.34,1.56,.64,1);\n  cursor:default; overflow:hidden; position:relative;\n}\n.ssk-tool-card::before {\n  content:\'\';\n  position:absolute; top:0; left:0; width:4px; height:100%;\n  background:linear-gradient(180deg,var(--blue),var(--blue-light));\n  transform:scaleY(0); transform-origin:top;\n  transition:transform .4s ease;\n}\n.ssk-tool-card:hover::before { transform:scaleY(1); }\n.ssk-tool-card:hover {\n  border-color:var(--sky);\n  background:var(--sky-pale);\n  transform:translateX(9px);\n  box-shadow:var(--sh-blue);\n}\n.ssk-tool-card:active { transform:scale(.97); }\n.ssk-tool-icon { font-size:1.65em; flex-shrink:0; transition:transform .4s cubic-bezier(.34,1.56,.64,1); }\n.ssk-tool-card:hover .ssk-tool-icon { transform:scale(1.22) rotate(-6deg); }\n.ssk-tool-card strong { display:block; color:var(--navy); font-size:1em; margin-bottom:3px; }\n.ssk-tool-card span { font-size:.87em; color:var(--slate); }\n\n/* ═══════════════════════════════\n   SERVICE CARDS\n═══════════════════════════════ */\n.ssk-svc-grid {\n  display:grid;\n  grid-template-columns:repeat(auto-fill,minmax(320px,1fr));\n  gap:24px;\n}\n.ssk-svc-card {\n  background:var(--white);\n  border:2px solid var(--gray-200);\n  border-radius:var(--r-xl);\n  padding:34px 30px;\n  box-shadow:var(--sh-sm);\n  transition:all .45s cubic-bezier(.22,1,.36,1);\n  cursor:default; position:relative; overflow:hidden;\n}\n.ssk-svc-card::before {\n  content:\'\';\n  position:absolute; top:0; left:0; right:0; height:5px;\n  background:linear-gradient(90deg,var(--blue-mid),var(--blue-light));\n  transform:scaleX(0); transform-origin:left;\n  transition:transform .45s ease;\n  border-radius:4px 4px 0 0;\n}\n.ssk-svc-card:hover::before { transform:scaleX(1); }\n.ssk-svc-card:hover {\n  border-color:var(--sky);\n  transform:translateY(-13px);\n  box-shadow:var(--sh-blue);\n}\n.ssk-svc-card:active { transform:translateY(-5px) scale(.98); }\n.ssk-svc-head {\n  display:flex; align-items:center; gap:15px;\n  margin-bottom:20px;\n}\n.ssk-svc-num {\n  background:linear-gradient(135deg,var(--blue),#1d4ed8);\n  color:var(--white);\n  font-family:\'Fraunces\',serif;\n  font-size:1.12em; font-weight:700;\n  width:46px; height:46px; flex-shrink:0;\n  border-radius:13px;\n  display:flex; align-items:center; justify-content:center;\n  box-shadow:0 5px 16px rgba(26,86,219,.35);\n  transition:transform .4s cubic-bezier(.34,1.56,.64,1);\n}\n.ssk-svc-card:hover .ssk-svc-num { transform:scale(1.14) rotate(-7deg); }\n.ssk-svc-card h3 { font-family:\'Fraunces\',serif; font-size:1.25em; color:var(--navy); }\n.ssk-svc-card ul { list-style:none; }\n.ssk-svc-card ul li {\n  padding:10px 0 10px 28px;\n  position:relative;\n  color:var(--slate); font-size:.95em;\n  border-bottom:1px solid var(--gray-100);\n  transition:color .25s, padding-left .25s;\n}\n.ssk-svc-card ul li:last-child { border-bottom:none; }\n.ssk-svc-card ul li::before {\n  content:\'›\';\n  position:absolute; left:8px;\n  color:var(--blue-light); font-weight:700;\n  transition:left .25s, color .25s;\n}\n.ssk-svc-card:hover ul li { color:var(--slate-dark); }\n.ssk-svc-card:hover ul li::before { left:13px; color:var(--blue); }\n.ssk-svc-note {\n  margin-top:15px; font-size:.88em; color:var(--slate);\n  font-style:italic; padding-top:12px; border-top:1px dashed var(--gray-200);\n}\n\n/* ═══════════════════════════════\n   PROCESS STEPS\n═══════════════════════════════ */\n.ssk-steps {\n  display:grid;\n  grid-template-columns:repeat(auto-fill,minmax(240px,1fr));\n  gap:15px;\n  counter-reset:step;\n}\n.ssk-step {\n  counter-increment:step;\n  background:var(--white);\n  border:2px solid var(--gray-200);\n  border-radius:15px;\n  padding:22px 20px 22px 76px;\n  position:relative;\n  box-shadow:var(--sh-sm);\n  font-weight:600; font-size:.98em;\n  transition:all .4s cubic-bezier(.34,1.56,.64,1);\n  cursor:default;\n}\n.ssk-step::before {\n  content:counter(step);\n  position:absolute; left:18px; top:50%; transform:translateY(-50%);\n  width:42px; height:42px;\n  background:linear-gradient(135deg,var(--blue),#1d4ed8);\n  color:var(--white);\n  border-radius:50%;\n  display:flex; align-items:center; justify-content:center;\n  font-weight:700; font-size:1.06em;\n  box-shadow:0 5px 16px rgba(26,86,219,.32);\n  transition:transform .4s cubic-bezier(.34,1.56,.64,1);\n}\n.ssk-step:hover {\n  border-color:var(--blue-light);\n  background:var(--sky-pale);\n  transform:translateX(11px);\n  box-shadow:var(--sh-blue);\n  color:var(--navy);\n}\n.ssk-step:hover::before { transform:translateY(-50%) scale(1.2); }\n.ssk-step:active { transform:scale(.97); }\n.ssk-step-desc {\n  font-weight:400; font-size:.86em; color:var(--slate);\n  margin-top:5px;\n}\n\n/* ═══════════════════════════════\n   BENEFITS\n═══════════════════════════════ */\n.ssk-benefits-grid {\n  display:grid;\n  grid-template-columns:repeat(auto-fill,minmax(220px,1fr));\n  gap:14px;\n}\n.ssk-benefit {\n  background:var(--white);\n  border:2px solid var(--gray-200);\n  border-radius:13px;\n  padding:22px 20px;\n  display:flex; align-items:center; gap:13px;\n  font-weight:500;\n  box-shadow:var(--sh-sm);\n  transition:all .4s cubic-bezier(.34,1.56,.64,1);\n  cursor:default;\n}\n.ssk-benefit-icon {\n  width:36px; height:36px; flex-shrink:0;\n  background:linear-gradient(135deg,var(--sky),#bfdbfe);\n  color:var(--blue);\n  border-radius:50%;\n  display:flex; align-items:center; justify-content:center;\n  font-size:1em; font-weight:700;\n  transition:background .3s, color .3s, transform .4s cubic-bezier(.34,1.56,.64,1);\n}\n.ssk-benefit:hover {\n  background:linear-gradient(135deg,var(--blue),#1d4ed8);\n  color:var(--white);\n  border-color:var(--blue);\n  transform:translateY(-8px) scale(1.04);\n  box-shadow:var(--sh-blue);\n}\n.ssk-benefit:hover .ssk-benefit-icon {\n  background:rgba(255,255,255,.22);\n  color:var(--white);\n  transform:scale(1.16);\n}\n\n/* ═══════════════════════════════\n   COMPARISON TABLE\n═══════════════════════════════ */\n.ssk-table-wrap {\n  overflow-x:auto;\n  border-radius:var(--r-lg);\n  box-shadow:var(--sh-md);\n  border:2px solid var(--gray-200);\n  margin-top:8px;\n}\n.ssk-table {\n  width:100%; border-collapse:collapse;\n  font-size:.95em;\n}\n.ssk-table thead tr {\n  background:linear-gradient(135deg,var(--navy),#1a3a6c);\n  color:var(--white);\n}\n.ssk-table thead th {\n  padding:16px 20px; text-align:left;\n  font-family:\'Fraunces\',serif;\n  font-size:.95em; font-weight:700;\n}\n.ssk-table tbody tr {\n  border-bottom:1px solid var(--gray-200);\n  transition:background .25s;\n}\n.ssk-table tbody tr:hover { background:var(--sky-pale); }\n.ssk-table tbody tr:last-child { border-bottom:none; }\n.ssk-table td { padding:14px 20px; color:var(--slate-dark); }\n.ssk-table td:first-child { font-weight:600; color:var(--navy); }\n.ssk-check { color:var(--green); font-weight:700; font-size:1.1em; }\n.ssk-cross { color:var(--red); font-weight:700; font-size:1.1em; }\n.ssk-hl-row { background:linear-gradient(90deg,var(--sky-pale),#e8f4ff) !important; }\n.ssk-hl-row td:first-child { color:var(--blue) !important; }\n\n/* ═══════════════════════════════\n   FAQ\n═══════════════════════════════ */\n.ssk-faq-list { margin-top:8px; }\n.ssk-faq-item {\n  border:2px solid var(--gray-200);\n  border-radius:14px;\n  margin-bottom:12px;\n  overflow:hidden;\n  transition:border-color .3s, box-shadow .3s;\n}\n.ssk-faq-item:hover { border-color:var(--sky); box-shadow:var(--sh-sm); }\n.ssk-faq-q {\n  padding:20px 24px;\n  display:flex; align-items:center; justify-content:space-between; gap:12px;\n  cursor:pointer;\n  font-weight:600; font-size:1.02em; color:var(--navy);\n  background:var(--white);\n  transition:background .25s, color .25s;\n  user-select:none;\n}\n.ssk-faq-q:hover { background:var(--sky-pale); color:var(--blue); }\n.ssk-faq-icon {\n  width:30px; height:30px; flex-shrink:0;\n  background:var(--sky); color:var(--blue);\n  border-radius:50%;\n  display:flex; align-items:center; justify-content:center;\n  font-size:1.1em; font-weight:700;\n  transition:all .35s cubic-bezier(.34,1.56,.64,1);\n}\n.ssk-faq-item.open .ssk-faq-icon {\n  background:var(--blue); color:var(--white);\n  transform:rotate(45deg);\n}\n.ssk-faq-a {\n  max-height:0; overflow:hidden;\n  transition:max-height .4s ease, padding .4s ease;\n  padding:0 24px;\n  font-size:.97em; color:var(--slate);\n  line-height:1.8;\n  background:var(--sky-pale);\n}\n.ssk-faq-item.open .ssk-faq-a {\n  max-height:300px;\n  padding:16px 24px 22px;\n}\n\n/* ═══════════════════════════════\n   RESULTS / NUMBERS\n═══════════════════════════════ */\n.ssk-results-row {\n  display:grid;\n  grid-template-columns:repeat(auto-fill,minmax(175px,1fr));\n  gap:16px;\n}\n.ssk-result-card {\n  background:linear-gradient(145deg,var(--navy),#1a3a6c);\n  border-radius:var(--r-lg);\n  padding:28px 20px;\n  text-align:center;\n  color:var(--white);\n  box-shadow:var(--sh-blue);\n  transition:all .4s cubic-bezier(.34,1.56,.64,1);\n  cursor:default;\n  position:relative; overflow:hidden;\n}\n.ssk-result-card::before {\n  content:\'\';\n  position:absolute; top:-20px; right:-20px;\n  width:80px; height:80px;\n  background:radial-gradient(circle,rgba(255,255,255,.08),transparent 70%);\n  border-radius:50%;\n}\n.ssk-result-card:hover {\n  transform:translateY(-10px) scale(1.04);\n  box-shadow:0 20px 50px rgba(26,86,219,.4);\n}\n.ssk-result-num {\n  font-family:\'Fraunces\',serif;\n  font-size:2.8em; font-weight:900;\n  color:var(--white); line-height:1;\n  margin-bottom:6px;\n}\n.ssk-result-num .gold { color:#fcd34d; }\n.ssk-result-label { font-size:.82em; color:rgba(255,255,255,.65); font-weight:600; text-transform:uppercase; letter-spacing:.5px; }\n\n/* ═══════════════════════════════\n   ALERT BOX\n═══════════════════════════════ */\n.ssk-alert {\n  border-radius:var(--r-md);\n  padding:20px 26px;\n  display:flex; align-items:flex-start; gap:14px;\n  margin:24px 0;\n}\n.ssk-alert.warning { background:#fffbeb; border-left:5px solid var(--gold); }\n.ssk-alert.info    { background:var(--sky-pale); border-left:5px solid var(--blue); }\n.ssk-alert.success { background:var(--green-light); border-left:5px solid var(--green); }\n.ssk-alert-icon { font-size:1.4em; flex-shrink:0; margin-top:1px; }\n.ssk-alert-content strong { display:block; color:var(--navy); margin-bottom:4px; }\n.ssk-alert-content span { font-size:.95em; color:var(--slate-dark); }\n\n/* ═══════════════════════════════\n   PRICING PREVIEW\n═══════════════════════════════ */\n.ssk-pricing-grid {\n  display:grid;\n  grid-template-columns:repeat(auto-fill,minmax(240px,1fr));\n  gap:20px;\n}\n.ssk-price-card {\n  background:var(--white);\n  border:2px solid var(--gray-200);\n  border-radius:var(--r-xl);\n  padding:32px 26px;\n  box-shadow:var(--sh-sm);\n  text-align:center;\n  transition:all .45s cubic-bezier(.34,1.56,.64,1);\n  cursor:default; position:relative; overflow:hidden;\n}\n.ssk-price-card.popular {\n  border-color:var(--blue);\n  background:linear-gradient(145deg,var(--sky-pale),#daeeff);\n  box-shadow:var(--sh-blue);\n}\n.ssk-price-badge {\n  position:absolute; top:18px; right:-30px;\n  background:var(--blue); color:var(--white);\n  font-size:.72em; font-weight:700;\n  padding:5px 38px;\n  transform:rotate(40deg);\n  letter-spacing:.5px; text-transform:uppercase;\n}\n.ssk-price-card:hover {\n  transform:translateY(-14px) scale(1.03);\n  box-shadow:var(--sh-blue);\n  border-color:var(--blue);\n}\n.ssk-price-name { font-family:\'Fraunces\',serif; font-size:1.2em; color:var(--navy); margin-bottom:6px; }\n.ssk-price-amount {\n  font-family:\'Fraunces\',serif;\n  font-size:2.2em; font-weight:900; color:var(--blue);\n  line-height:1; margin:12px 0 6px;\n}\n.ssk-price-period { font-size:.8em; color:var(--slate); margin-bottom:18px; }\n.ssk-price-features { list-style:none; text-align:left; margin-bottom:20px; }\n.ssk-price-features li {\n  padding:8px 0 8px 24px; position:relative;\n  font-size:.9em; color:var(--slate-dark);\n  border-bottom:1px solid var(--gray-100);\n}\n.ssk-price-features li:last-child { border-bottom:none; }\n.ssk-price-features li::before { content:\'✓\'; position:absolute; left:0; color:var(--green); font-weight:700; }\n\n/* ═══════════════════════════════\n   CONTACT SECTION\n═══════════════════════════════ */\n.ssk-contact {\n  background:linear-gradient(150deg,var(--navy) 0%,#0f3875 50%,#1a56cc 100%);\n  border-radius:0;\n  padding:80px 32px 90px;\n  color:var(--white);\n  text-align:center;\n  position:relative; overflow:hidden;\n  margin-top:60px;\n}\n.ssk-contact-mesh {\n  position:absolute; inset:0; pointer-events:none;\n  background:\n    radial-gradient(circle at 18% 65%, rgba(26,108,246,.38) 0%, transparent 55%),\n    radial-gradient(circle at 82% 22%, rgba(245,158,11,.2) 0%, transparent 50%),\n    radial-gradient(circle at 50% 90%, rgba(96,165,250,.2) 0%, transparent 50%);\n}\n.ssk-contact-grid {\n  position:absolute; inset:0; pointer-events:none;\n  background-image:\n    linear-gradient(rgba(255,255,255,.04) 1px,transparent 1px),\n    linear-gradient(90deg,rgba(255,255,255,.04) 1px,transparent 1px);\n  background-size:34px 34px;\n}\n.ssk-contact h2 {\n  font-family:\'Fraunces\',serif;\n  font-size:clamp(1.9em,4vw,2.8em);\n  position:relative; z-index:2; margin-bottom:12px;\n}\n.ssk-contact > p {\n  opacity:.82; font-size:1.12em;\n  position:relative; z-index:2; margin-bottom:44px;\n  max-width:620px; margin-left:auto; margin-right:auto;\n}\n.ssk-contact-cards {\n  display:flex; flex-wrap:wrap; justify-content:center; gap:20px;\n  margin-bottom:48px; position:relative; z-index:2;\n}\n.ssk-contact-card {\n  background:rgba(255,255,255,.1);\n  border:1.5px solid rgba(255,255,255,.22);\n  border-radius:18px;\n  padding:22px 32px;\n  min-