(2739, 0, '2026-02-24 14:55:05', '2026-02-24 14:55:05', '{\"subject\":\"[seoservicessk.com] SEO Services SK\",\"ip\":\"223.181.54.69\",\"country_code\":null,\"user_agent\":\"Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/145.0.0.0 Safari/537.36\",\"notification_recipients\":[],\"entry_title\":\"SEO Services SK\",\"entry_page\":1,\"source_id\":1204,\"source_type\":\"single\",\"request_url\":\"https://seoservicessk.com\",\"fields\":[{\"key\":\"1_Name\",\"label\":\"Name\",\"value\":\"Sujit Pujari\",\"type\":\"name\",\"meta\":[],\"form_field_id\":\"g1204-name\"},{\"key\":\"2_Email\",\"label\":\"Email\",\"value\":\"sujit.webseoconsultant@gmail.com\",\"type\":\"email\",\"meta\":[],\"form_field_id\":\"g1204-email\"},{\"key\":\"3_Message\",\"label\":\"Message\",\"value\":\"Hi There,\\r\\n\\r\\nQuick question \\u2014 who handles link building decisions at seo services sk?\\r\\n\\r\\nIf that\\u2019s you, I have a quick capacity question.\\r\\nIf not, could you please point me to the right person?\\r\\n\\r\\nThanks so much!\\r\\nSujit.\",\"type\":\"textarea\",\"meta\":[],\"form_field_id\":\"g1204-message\"}]}', 'Sujit Pujari - 2026-02-24 14:55:05', '', 'publish', 'open', 'closed', '', '572ef4f28c17715a198c787a08559c16', '', '', '2026-02-24 14:55:05', '2026-02-24 14:55:05', '', 1204, 'https://seoservicessk.com/?post_type=feedback&p=2739', 0, 'feedback', 'v3', 0);
