(2794, 0, '2026-03-17 21:27:13', '2026-03-17 21:27:13', '{\"subject\":\"[seoservicessk.com] Contact\",\"ip\":\"50.114.206.14\",\"country_code\":null,\"user_agent\":\"Mozilla/5.0 (Windows NT 10.0; WOW64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/114.0.0.0 Safari/537.36 Vivaldi/5.3.2679.68\",\"notification_recipients\":[],\"entry_title\":\"Contact\",\"entry_page\":1,\"source_id\":790,\"source_type\":\"single\",\"request_url\":\"https://seoservicessk.com/contact-us\",\"fields\":[{\"key\":\"1_Name\",\"label\":\"Name\",\"value\":\"Amanda Anderson\",\"type\":\"name\",\"meta\":[],\"form_field_id\":\"g790-name\"},{\"key\":\"2_Email\",\"label\":\"Email\",\"value\":\"amanda@seoleads.me\",\"type\":\"email\",\"meta\":[],\"form_field_id\":\"g790-email\"},{\"key\":\"3_Message\",\"label\":\"Message\",\"value\":\"Hi,\\r\\nI wasn\\u2019t able to connect via email or LinkedIn, so I thought I\\u2019d reach out here.\\r\\nWe generate exclusive SEO and web design leads:\\r\\n* $25 for exclusive appointment - Fixed leads\\r\\n* $15 per lead\\r\\n* You only pay for real requests\\r\\n* Leads are never shared or resold\\r\\n* Unqualified leads are replaced\\r\\nWould you be open to testing a small batch to see how it works?\\r\\n\\r\\nwww.seoleads.me\\r\\nAmanda Anderson\",\"type\":\"textarea\",\"meta\":[],\"form_field_id\":\"g790-message\"}]}', 'Amanda Anderson - 2026-03-17 21:27:13', '', 'publish', 'open', 'closed', '', '2540f988a6f6f0bbabcc46f71dd2d307', '', '', '2026-03-17 21:27:13', '2026-03-17 21:27:13', '', 790, 'https://seoservicessk.com/?post_type=feedback&p=2794', 0, 'feedback', 'v3', 0),
(2795, 0, '2026-03-18 15:40:35', '2026-03-18 15:40:35', '{\"subject\":\"[seoservicessk.com] Contact\",\"ip\":\"50.114.206.14\",\"country_code\":null,\"user_agent\":\"Mozilla/5.0 (Windows NT 10.0; WOW64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/114.0.0.0 YaBrowser/22.7.0 Yowser/2.5 Safari/537.36\",\"notification_recipients\":[],\"entry_title\":\"Contact\",\"entry_page\":1,\"source_id\":790,\"source_type\":\"single\",\"request_url\":\"https://seoservicessk.com/contact-us\",\"fields\":[{\"key\":\"1_Name\",\"label\":\"Name\",\"value\":\"Amanda Anderson\",\"type\":\"name\",\"meta\":[],\"form_field_id\":\"g790-name\"},{\"key\":\"2_Email\",\"label\":\"Email\",\"value\":\"amanda@seoleads.me\",\"type\":\"email\",\"meta\":[],\"form_field_id\":\"g790-email\"},{\"key\":\"3_Message\",\"label\":\"Message\",\"value\":\"Hi,\\r\\nI wasn\\u2019t able to connect via email or LinkedIn, so I thought I\\u2019d reach out here.\\r\\nWe generate exclusive SEO and web design leads:\\r\\n* $25 for exclusive appointment - Fixed leads\\r\\n* $15 per lead\\r\\n* You only pay for real requests\\r\\n* Leads are never shared or resold\\r\\n* Unqualified leads are replaced\\r\\nWould you be open to testing a small batch to see how it works?\\r\\n\\r\\nwww.seoleads.me\\r\\nAmanda Anderson\",\"type\":\"textarea\",\"meta\":[],\"form_field_id\":\"g790-message\"}]}', 'Amanda Anderson - 2026-03-18 15:40:35', '', 'publish', 'open', 'closed', '', '396cda045908cfcf7867dacd672bb31e', '', '', '2026-03-18 15:40:35', '2026-03-18 15:40:35', '', 790, 'https://seoservicessk.com/?post_type=feedback&p=2795', 0, 'feedback', 'v3', 0),
(2796, 0, '2026-03-18 16:36:15', '2026-03-18 16:36:15', '{\"subject\":\"[seoservicessk.com] SEO Services SK\",\"ip\":\"72.57.111.191\",\"country_code\":null,\"user_agent\":\"Mozilla/5.0 (Linux; Android 5.0; SM-G900P Build/LRX21T) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/59.0.9988.1427 Mobile Safari/537.36\",\"notification_recipients\":[],\"entry_title\":\"SEO Services SK\",\"entry_page\":1,\"source_id\":1204,\"source_type\":\"single\",\"request_url\":\"https://seoservicessk.com\",\"fields\":[{\"key\":\"1_Name\",\"label\":\"Name\",\"value\":\"Sarah Wilson\",\"type\":\"name\",\"meta\":[],\"form_field_id\":\"g1204-name\"},{\"key\":\"2_Email\",\"label\":\"Email\",\"value\":\"sarahwil@circuitprompt.com\",\"type\":\"email\",\"meta\":[],\"form_field_id\":\"g1204-email\"},{\"key\":\"3_Message\",\"label\":\"Message\",\"value\":\"Hi there,\\r\\n\\r\\nMy earlier email bounced, so I\\u2019m reaching out here.\\r\\n\\r\\nMost digital teams do a great job driving conversations, but once the DMs start flowing, high-intent leads vanish in the noise because the volume outpaces the system.\\r\\n\\r\\nThat\\u2019s why we built FlowChat, and why we just released a playbook featuring the exact scripts responsible for over $4M in closed deals. 17 real conversations that turn cold DMs into real revenue without the spam.\\r\\n\\r\\nInterested? Reply \\\"FLOW\\\" and it\\u2019s yours.\\r\\n\\r\\nBest, \\r\\nSarah\",\"type\":\"textarea\",\"meta\":[],\"form_field_id\":\"g1204-message\"}]}', 'Sarah Wilson - 2026-03-18 16:36:15', '', 'publish', 'open', 'closed', '', '034f212cca0a450dae8719b120fd2e4f', '', '', '2026-03-18 16:36:15', '2026-03-18 16:36:15', '', 1204, 'https://seoservicessk.com/?post_type=feedback&p=2796', 0, 'feedback', 'v3', 0);
