(2833, 0, '2026-04-12 11:19:53', '2026-04-12 11:19:53', '{\"subject\":\"[seoservicessk.com] SEO Services SK\",\"ip\":\"213.176.64.22\",\"country_code\":null,\"user_agent\":\"Mozilla/5.0 (Windows NT 10.0; Win64; x64; rv:114.0) Gecko/20100101 Firefox/114.0\",\"notification_recipients\":[],\"entry_title\":\"SEO Services SK\",\"entry_page\":1,\"source_id\":1204,\"source_type\":\"single\",\"request_url\":\"https://seoservicessk.com\",\"fields\":[{\"key\":\"1_Name\",\"label\":\"Name\",\"value\":\"Kimberley Holland\",\"type\":\"name\",\"meta\":[],\"form_field_id\":\"g1204-1-name\"},{\"key\":\"2_Email\",\"label\":\"Email\",\"value\":\"kimberley@virtualeaseservice.com\",\"type\":\"email\",\"meta\":[],\"form_field_id\":\"g1204-1-email\"},{\"key\":\"3_Message\",\"label\":\"Message\",\"value\":\"Hi there, \\r\\n\\r\\nI\\u2019m Kimberley with Virtual Ease Service, and we help business owners secure more booked appointments using our Lead Found system. On average, our clients see 10 new appointments every day.\\r\\n\\r\\nWould you be interested in bringing in more qualified leads for your business?\\r\\n\\r\\n\\r\\nKimberley\",\"type\":\"textarea\",\"meta\":[],\"form_field_id\":\"g1204-1-message\"}]}', 'Kimberley Holland - 2026-04-12 11:19:53', '', 'publish', 'open', 'closed', '', 'ce1d1f1db15caed3b070bd86153d79d8', '', '', '2026-04-12 11:19:53', '2026-04-12 11:19:53', '', 1204, 'https://seoservicessk.com/?post_type=feedback&p=2833', 0, 'feedback', 'v3', 0);
